/**
 * Svara lokalt med faktorfäder-mönstret — eller null (då har hela kedjan
 * före redan lämnat null och API-flödet tar över). Ligger mot kedjans
 * slut — efter agarslut, FÖRE marknadsrytm (deras permanenta SIST-
 * deklaration) — och kan därför aldrig stjäla en fråga från ett tidigare
 * lager. Dokumenterade gränser: «mr market» → grahamgolvet ·
 * «faktorpremien» → faktordjupet · «värdefälla» → agarslut · «ev/ebit»
 * naket → redovisningsdjupet · «p/s»/«p/e» naket → multipel/pe-mekanik ·
 * «överreaktion» → förväntningsdjupet. Samma matchningssemantik som
 * basmotorn: minst ett kärnord krävs, poäng = kärnord × 3 + stärkord,
 * oavgjort → först deklarerade mönstret vinner (strikt >, deterministiskt).
 * Samma fråga ⇒ bitidentiskt svar.
 */
export function svaraLokaltFaktorfadrarna(fraga: string, register: RegisterRad[]): LokaltSvar | null {
  const fragaStr = diafri(fraga);
  if (!fragaStr) return null;
  const fragaOrd = fragaStr.split(" ");
  let bast: { svar: LokaltSvar; poang: number } | null = null;
  for (const m of FAKTORFADRARNA_MONSTER) {
    const karnTraff = m.karnord.filter((nk) => traff(fragaOrd, fragaStr, nk));
    if (karnTraff.length === 0) continue; // krav: minst ett kärnord
    const starkTraff = m.starkord?.filter((nk) => traff(fragaOrd, fragaStr, nk)) ?? [];
    const poang = karnTraff.length * 3 + starkTraff.length;
    if (!bast || poang > bast.poang) bast = { svar: m.bygga(register), poang };
  }
  return bast ? bast.svar : null;
}
